const ORIGIN = SITE.domain;

/** Parse a leading `---` block into a flat key -> value map. */
function parseFrontmatter(md: string): Record<string, string> {
	expect(md.startsWith("---\n"), "document does not open with ---").toBe(true);
	const end = md.indexOf("\n---\n", 3);
	expect(end, "unterminated frontmatter block").toBeGreaterThan(0);
	const out: Record<string, string> = {};
	for (const line of md.slice(4, end).split("\n")) {
		const at = line.indexOf(": ");
		if (at === -1) continue;
		out[line.slice(0, at)] = JSON.parse(line.slice(at + 2)) as string;
	}
	return out;
}

