describe("Markdown alternate is advertised only where a twin exists", () => {
	it("the root layout advertises the site root's Markdown twin", () => {
		const types = rootMetadata.alternates?.types as
			| Record<string, unknown>
			| undefined;
		expect(types?.["text/markdown"]).toBe(`${ORIGIN}/index.md`);
	});

	it("the advertised root URL is one middleware actually rewrites", () => {
		// The whole point of the link is that following it returns Markdown. If
		// mdTarget() ever stops mapping /index.md, the link becomes a lie.
		const res = middleware(
			new NextRequest(`${ORIGIN}/index.md`, {
				headers: { accept: "*/*", "x-real-ip": "198.51.100.11" },
			}),
		);
		expect(res?.headers.get("x-middleware-rewrite")).toContain("/api/md");
	});

	it("every marketing page keeps its own alternates, so none inherits the link", () => {
		// Next merges metadata shallowly per top-level key: a page that declares
		// `alternates` replaces the layout's object entirely. These 13 pages have
		// no Markdown twin in mdTarget(), so that replacement is the only thing
		// keeping a false rel="alternate" off them.
		const pages = [
			"about",
			"alternatives",
			"api-policy",
			"best-claude-code-plugins",
			"claude-agent-sdk-vs-claude-code-plugins",
			"compare",
			"contact",
			"developers",
			"pricing",
			"privacy",
			"status",
			"terms",
			"yonyon",
		];
		for (const page of pages) {
			const src = readFileSync(
				resolve(__dirname, `../app/(home)/${page}/page.tsx`),
				"utf8",
			);
			expect(src, `${page}/page.tsx declares no alternates`).toContain(
				"alternates:",
			);
			expect(src, `${page}/page.tsx declares no canonical`).toContain(
				"canonical:",
			);
			// The metadata KEY form, quoted and followed by a colon. Prose that
			// mentions `Accept: text/markdown` (as /developers does) is not a claim
			// about this page's own alternate representations.
			expect(
				src.includes('"text/markdown":'),
				`${page}/page.tsx advertises a Markdown alternate it does not have`,
			).toBe(false);
		}
	});

	it("a docs page advertises its own .md URL, and that URL rewrites", () => {
		const res = middleware(
			new NextRequest(`${ORIGIN}/docs/foundations/overview.md`, {
				headers: { accept: "*/*", "x-real-ip": "198.51.100.12" },
			}),
		);
		expect(res?.headers.get("x-middleware-rewrite")).toContain(
			"/api/md/foundations/overview",
		);
	});

	it("the docs index advertises /docs.md, which also rewrites", () => {
		// Built from the slug, not from the canonical URL: the naive `${url}.md`
		// produces "/docs/.md" for the empty-slug index.
		const res = middleware(
			new NextRequest(`${ORIGIN}/docs.md`, {
				headers: { accept: "*/*", "x-real-ip": "198.51.100.13" },
			}),
		);
		expect(res?.headers.get("x-middleware-rewrite")).toContain("/api/md");
	});
});

// ---------------------------------------------------------------- B2

describe("frontmatter rendering", () => {
	it("escapes quotes and folds newlines so the block cannot be broken", () => {
		const block = frontmatterBlock({
			title: 'A "quoted" title',
			description: "line one\nline two",
			canonical: `${ORIGIN}/x`,
		});
		expect(block).toContain('title: "A \\"quoted\\" title"');
		expect(block).toContain('description: "line one line two"');
		// Exactly one opening and one closing delimiter.
		expect(block.split("\n").filter((l) => l === "---")).toHaveLength(2);
	});

	it("omits description rather than inventing one", () => {
		const block = frontmatterBlock({ title: "T", canonical: `${ORIGIN}/x` });
		expect(block).not.toContain("description:");
	});

	it("leaves a blank line between the block and the body", () => {
		expect(withFrontmatter({ title: "T", canonical: "u" }, "# T\n")).toContain(
			"---\n\n# T",
		);
	});
});

describe("standalone Markdown routes open with frontmatter", () => {
	it.each([
		["pricing.md", getPricingMd, `${ORIGIN}/pricing`],
		["auth.md", getAuthMd, `${ORIGIN}/auth.md`],
		["api-policy.md", getApiPolicyMd, `${ORIGIN}/api-policy`],
	] as const)("%s names title, description and canonical", async (
		_name,
		get,
		canonical,
	) => {
		const fm = parseFrontmatter(await get().text());
		expect(fm.title.length).toBeGreaterThan(0);
		expect(fm.description.length).toBeGreaterThan(0);
		expect(fm.canonical).toBe(canonical);
	});

	it("the frontmatter title matches the document's own H1", async () => {
		for (const get of [getPricingMd, getAuthMd, getApiPolicyMd]) {
			const md = await get().text();
			const fm = parseFrontmatter(md);
			const h1 = md.split("\n").find((l) => l.startsWith("# "))?.slice(2);
			expect(h1).toBe(fm.title);
		}
	});

	it("the frontmatter description matches the document's own lead", async () => {
		// The blockquote and the frontmatter render from one constant, so a copy
		// edit to either cannot leave the two representations disagreeing.
		for (const get of [getPricingMd, getAuthMd, getApiPolicyMd]) {
			const md = await get().text();
			const fm = parseFrontmatter(md);
			const lead = md.split("\n").find((l) => l.startsWith("> "))?.slice(2);
			expect(lead).toBe(fm.description);
		}
	});

	it("the headers contract is unchanged by the frontmatter", async () => {
		for (const get of [getPricingMd, getAuthMd, getApiPolicyMd]) {
			const res = get();
			expect(res.status).toBe(200);
			expect(res.headers.get("Content-Type")).toBe(
				"text/markdown; charset=utf-8",
			);
		}
	});
});

