describe("ARD catalog trust", () => {
	type TrustManifest = {
		identity: string;
		identityType: string;
		provenance: { relation: string; sourceId: string }[];
	};
	type Catalog = {
		host: { identifier: string; trustManifest: TrustManifest };
		entries: { identifier: string; trustManifest?: TrustManifest }[];
	};

	async function catalog(): Promise<Catalog> {
		return (await getAiCatalog().json()) as Catalog;
	}

	it("EVERY entry carries a trustManifest, not just the host", async () => {
		const c = await catalog();
		expect(c.entries.length).toBe(5);
		for (const entry of c.entries) {
			expect(
				entry.trustManifest,
				`${entry.identifier} has no trustManifest`,
			).toBeDefined();
		}
	});

	it("each entry's identity is the host did:web, resolvable at did.json", async () => {
		const c = await catalog();
		const expected = `did:web:${ORIGIN.replace(/^https?:\/\//, "")}`;
		expect(c.host.trustManifest.identity).toBe(expected);
		for (const entry of c.entries) {
			expect(entry.trustManifest?.identity).toBe(expected);
			expect(entry.trustManifest?.identityType).toBe("did");
		}
	});

	it("provenance points at the public repository these resources ship from", async () => {
		const c = await catalog();
		for (const entry of c.entries) {
			expect(entry.trustManifest?.provenance).toEqual([
				{
					relation: "publishedFrom",
					sourceId: "https://github.com/yonatangross/orchestkit",
				},
			]);
		}
	});

	it("claims nothing it cannot back", async () => {
		// signature / attestations / trustSchema are absent by design: no
		// request-signing bot, no compliance program, no external governance.
		const c = await catalog();
		for (const tm of [
			c.host.trustManifest,
			...c.entries.map((e) => e.trustManifest),
		]) {
			expect(Object.keys(tm ?? {}).sort()).toEqual([
				"identity",
				"identityType",
				"provenance",
			]);
		}
	});
});
